// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;
    function setUp() public {
        c = new Owned();
        admin = address(this);
    }
    function testFuzz_property(address caller) public {
        vm.assume(caller != admin);
        vm.prank(admin);
        address initialOwner = c.owner();
        vm.prank(caller);
        bool ok;
        try c.setOwner(address(0x1234)) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        bool ownerUnchanged = (c.owner() == initialOwner);
        assertTrue(!ok && ownerUnchanged);
    }
}
